        B = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)))
    elif mode == "reverse":
        A = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)), reverse=True)
        B = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)), reverse=True)
    elif mode == "extreme":
        A = [draw(st.sampled_from([1, 10])) for _ in range(n)]
        B = [draw(st.sampled_from([1, 10])) for _ in range(n)]
    else:
        A = draw(st.lists(st.integers(1, 10), min_size=n, max_size=n))
        B = draw(st.lists(st.integers(1, 10), min_size=n, max_size=n))
    return f"{json.dumps(A)}\n{json.dumps(B)}\n"


def validate(inp):
    try:
        lines = [l for l in inp.split("\n") if l.strip()]
        if len(lines) != 2:
            return False
        A = json.loads(lines[0])
        B = json.loads(lines[1])
        if not (isinstance(A, list) and isinstance(B, list)):
            return False
