        if len(B) != n or not (3 <= n <= 10**5):
            return False
        for x in A + B:
            if not isinstance(x, int) or isinstance(x, bool):
                return False
            if not (1 <= x <= 10**5):
                return False
        return True
    except Exception:
        return False


def ref(inp):
    lines = [l for l in inp.split("\n") if l.strip()]
    A = json.loads(lines[0])
    B = json.loads(lines[1])
    n = len(A)
    best = 0
    # Each hour is 'A' (drink A), 'B' (drink B), or 'S' (wasted cleansing hour).
    # Rules: a switch between different drinks needs exactly one 'S' between them;
    # no 'S' between equal drinks; no leading or trailing 'S'.
    for seq in product("ABS", repeat=n):
        ok = True
        total = 0
        last = None
        s = 0
        for i, c in enumerate(seq):
            if c == "S":
                if last is None:
                    ok = False
                    break
                s += 1
                continue
            if last is not None:
                if c == last:
                    if s != 0:
                        ok = False
                        break
                else:
                    if s != 1:
                        ok = False
                        break
            total += A[i] if c == "A" else B[i]
            last = c
            s = 0
        if ok and s == 0 and last is not None:
            best = max(best, total)
    return json.dumps(best)
